bool containsNearbyDuplicate(vector<int>& nums, int k) {
    unordered_map<int,int> seen;           // maps value to position
    for (int i = 0; i < (int)nums.size(); ++i) {
        if (seen.find(nums[i]) != seen.end() && (i - seen[nums[i]]) <= k)
